$:set -euo pipefail
gh auth setup-git
git fetch origin main
git checkout --detach origin/main >/dev/null
DEST='workspaces/shared-conversations/6aec454d-4cdc-83e8-97b3-6fe58aeab10a/42001813950-1'
TEMP="$(mktemp -d)"
trap 'rm -rf "$TEMP"' EXIT
gh run download 42001813950 --repo BestNameYet/Terminals --name chatgpt-shared-export-final-attestation-42001813950-1 --dir "$TEMP"
node workspaces/extractor-srs-design/acceptance/verify-live-export.js "$DEST" "$TEMP/final-attestation.json"
node - "$DEST" "$TEMP/final-attestation.json" <<'NODE'
"use strict";
const fs=require("node:fs"),path=require("node:path"),assert=require("node:assert/strict");
const dir=process.argv[2],att=JSON.parse(fs.readFileSync(process.argv[3],"utf8"));
const visible=JSON.parse(fs.readFileSync(path.join(dir,"conversation.json"),"utf8"));
const linear=JSON.parse(fs.readFileSync(path.join(dir,"linear-conversation.json"),"utf8"));
const receipt=JSON.parse(fs.readFileSync(path.join(dir,"receipt.json"),"utf8"));
const empty=visible.messages.map((m,index)=>({index,role:m.role,text:m.text})).filter(m=>typeof m.text==="string"&&m.text.length===0);
const recovered=linear.records.filter(r=>r.raw_node?.content===""&&r.raw_node?.reasoningSummary).map(r=>({index:r.index,summary:r.raw_node.reasoningSummary,derived_text:r.derived_text}));
assert.equal(att.verification,"VERIFIED");
assert.equal(att.paths.length,8);
assert.equal(receipt.decoder_version,"1.0.1");
console.log(JSON.stringify({published_commit:att.published_commit_sha,output_directory:dir,decoder_version:receipt.decoder_version,coverage:visible.coverage,visible_messages:visible.messages.length,linear_records:linear.records.length,empty_visible_records:empty,recovered_empty_reasoning_summary_records:recovered,verified_paths:att.paths.length}));
NODE
